# Kaggle script kernel (CPU): Dynamo dynamic-shape leads (f-string format spec, namedtuple ==) and dtype leads on Linux, torch 2.14.0 then nightly.
import base64, subprocess, sys
open("diag_dynamic_fstring_namedtuple.py", "wb").write(base64.b64decode(""))
open("diag_dtype_leads.py", "wb").write(base64.b64decode(""))
subprocess.run(["pip", "-q", "install", "torch==2.14.0", "--index-url", "https://download.pytorch.org/whl/cpu"])
