subprocess.run([sys.executable, "diag_dtype_leads.py"])
subprocess.run(["pip", "-q", "install", "--pre", "--upgrade", "torch", "--index-url", "https://download.pytorch.org/whl/nightly/cpu"])
subprocess.run([sys.executable, "diag_dynamic_fstring_namedtuple.py"])
subprocess.run([sys.executable, "diag_dtype_leads.py"])
